select * from mytable limit 8;

-- Q1 what is the revenue generated by the male vs female customers ?

select sum(purchase_amount)as total_purchase,gender
from mytable
group by gender;

-- Q2 Which customers used a discount but still spent more than the average purchase amount ? 

select customer_id,purchase_amount 
from mytable 
where discount_applied = 'Yes' 
and 
purchase_amount >= (select avg(purchase_amount) from mytable);


DESCRIBE mytable;

-- Q3 Which are the top 5 products with the highest average review rating ?

select item_purchased ,round(avg(review_rating),2) as avg_review_rating
from mytable
group by item_purchased
order by avg_review_rating desc
limit 5;
;
-- Q4 Compare the average Purchase amounts standard and express shipping.

select  shipping_type, round(avg(purchase_amount),2) as avg_purchase_amount
from mytable
where shipping_type in ('Standard' , 'Express')
group by shipping_type
;

-- Q5 Do Subscribed customers spend more ? compare average spend and total revenue between subscribers and non - subscribers 

select subscription_status , count(customer_id) as total_customers,
round(avg(purchase_amount),2) as average_spend,round(sum(purchase_amount),2) as total_revenue
from mytable
group by subscription_status
order by total_revenue,average_spend desc;

-- Q6 Which 5 products have the highest percentage of purchases with discounts applied ?

select item_purchased,
round(100*sum(case when discount_applied='Yes' then 1 else 0 end )/ count(*),2) as discount_rate
from mytable
group by item_purchased
order by discount_rate desc 
limit 5;

-- Q7 segment customers into New,Returning, and Loyal based on their total number of previous purchases , and show the count of each segment.

with customer_type as (select previous_purchases,
case 
when previous_purchases < 2 then 'New'
when previous_purchases >1 and previous_purchases<= 10 then 'Returning'
else 'Loyal'
end as customer_segment 
from mytable
)
select customer_segment ,count(*)
from customer_type 
group by customer_segment;

-- Q8 What are the top 3 most purchased products within the each category 

with item_counts as (
select category,item_purchased,
count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id)desc) as item_rank
from mytable
group by category, item_purchased
)
select item_rank,category,item_purchased,total_orders
from item_counts
where item_rank<=3;

-- Q9 Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
 
 select subscription_status,count(customer_id) as repeat_buyers
 from mytable
 where previous_purchases>5 
 group by subscription_status;
 
 -- Q10 what is the revenue contribution of each age group?
 
 select age_group, sum(purchase_amount) as total_revenue
 from mytable
 group by age_group
 order by total_revenue desc;